mapper.sql:
WHERE v.effective_date>=#{start} AND v.effective_date<#{end}
AND v.contract_type=#{type}
AND v.customer_id=#{customerId}
AND (v.project_name ILIKE '%'||#{q}||'%' OR v.bill_no ILIKE '%'||#{q}||'%' OR v.customer_name ILIKE '%'||#{q}||'%')


    AND v.bill_stts_cd='CONFIRM' AND v.receivable_amt=0
    AND v.receivable_amt>0
    AND v.receivable_amt>0 AND v.rcpt_plan_dt<#{today}
    AND v.bill_stts_cd=#{status}

mapper.select:
SELECT v.* FROM () v ORDER BY
v.bill_no v.project_name v.sply_amt v.vat_amt v.tot_amt v.rcpt_plan_dt v.received_amt v.receivable_amt v.bill_stts_cd v.atrb_ym v.bill_dt
ASCDESC NULLS LAST,v.bill_id ASC NULLS LAST,v.bill_stg_id ASC LIMIT #{size} OFFSET #{offset}
